INSERT INTO `nodes` (`id`, `parent_id`, `type`, `title`, `description`, `icon`, `display_order`, `view_level`, `thread_level`, `reply_level`, `hide_if_no_access`, `is_closed`, `quick_nav`, `require_prefix`, `default_prefix_id`, `title_hint`, `thread_template`, `form_json`) VALUES
  (1, NULL, 'category', 'Главный раздел', '', 'chats', 1, 0, 10, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (10, 1, 'forum', 'Новости и информация', 'Обновления сервера, анонсы и важные объявления администрации', 'megaphone', 1, 0, 80, 80, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (11, 10, 'forum', 'Обновления сервера', 'Списки изменений после каждого обновления мода', 'refresh', 1, 0, 80, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (12, 10, 'forum', 'Мероприятия и конкурсы', 'Анонсы ивентов, конкурсов и их итоги', 'star', 2, 0, 40, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (20, 1, 'forum', 'Технический раздел', 'Помощь с игрой, клиентом и ошибками мода', 'wrench', 2, 0, 80, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (21, 20, 'forum', 'Техническая поддержка', 'Не запускается игра, вылеты, проблемы со входом', 'help', 1, 0, 10, 10, 0, 0, 9, 0, 11, 'Кратко опишите проблему', '[b]1. Игровой ник:[/b] \n[b]2. Опишите проблему:[/b] \n[b]3. Когда она началась:[/b] \n[b]4. Что уже пробовали сделать:[/b] \n[b]5. Скриншоты или видео:[/b] ', '{"title": "{problem}", "fields": [{"key": "nick", "label": "Игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "problem", "label": "Кратко о проблеме", "type": "text", "required": true, "placeholder": "Например: вылет при входе на сервер", "max": 100}, {"key": "essence", "label": "Подробное описание", "type": "textarea", "required": true}, {"key": "tried", "label": "Что уже пробовали сделать", "type": "textarea"}, {"key": "proof", "label": "Скриншот или видео", "type": "url", "hint": "Загрузите скриншот на imgur.com или yapx.ru и вставьте ссылку."}]}'),
  (22, 20, 'forum', 'Баги и ошибки мода', 'Нашли ошибку в игре - опишите, как её повторить', 'alert', 2, 0, 10, 10, 0, 0, 0, 0, 11, 'Где и в чём ошибка', '[b]1. Игровой ник:[/b] \n[b]2. Где найдена ошибка:[/b] \n[b]3. Как её повторить (по шагам):[/b] \n[b]4. Что должно было произойти:[/b] \n[b]5. Скриншоты или видео:[/b] ', NULL),
  (30, 1, 'forum', 'Правила проекта', 'Правила сервера, форума и организаций', 'rules', 3, 0, 80, 80, 0, 0, 1, 0, NULL, NULL, NULL, NULL),
  (31, 30, 'forum', 'Общие правила сервера', '', 'rules', 1, 0, 80, 80, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (32, 30, 'forum', 'Правила форума', '', 'rules', 2, 0, 80, 80, 0, 0, 2, 0, NULL, NULL, NULL, NULL),
  (33, 30, 'forum', 'Правила государственных организаций', '', 'shield', 3, 0, 80, 80, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (34, 30, 'forum', 'Правила криминальных организаций', '', 'flag', 4, 0, 80, 80, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (40, 1, 'forum', 'Предложения по улучшению игры (мода)', 'Идеи для сервера: новые системы, работы, изменения баланса', 'lightbulb', 4, 0, 10, 10, 0, 0, 0, 0, 1, 'Коротко о предложении', '[b]1. Суть предложения:[/b] \n[b]2. Что изменится в игре:[/b] \n[b]3. Почему это сделает игру лучше:[/b] ', NULL),
  (41, 40, 'forum', 'Рассмотренные предложения', 'Предложения, по которым принято решение', 'check-all', 1, 0, 40, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (2, NULL, 'category', 'Раздел игрового сервера', '', 'chats', 2, 0, 10, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (50, 2, 'forum', 'Сервер Los Santos', 'Всё о жизни на сервере: жалобы, организации, заявления, торговля', 'server', 1, 0, 80, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (51, 50, 'forum', 'Жалобы', 'Жалобы на игроков, администрацию и лидеров, обжалование наказаний', 'flag', 1, 0, 80, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (52, 51, 'forum', 'Жалобы на игроков', 'Нарушение правил сервера игроками', 'flag', 1, 0, 10, 10, 0, 0, 3, 1, 1, 'Жалоба на Nick_Name', '[b]1. Ваш игровой ник:[/b] \n[b]2. Игровой ник нарушителя:[/b] \n[b]3. Суть нарушения:[/b] \n[b]4. Дата и время нарушения (МСК):[/b] \n[b]5. Доказательства (скриншоты, видео):[/b] ', '{"title": "Жалоба на {offender} | {rule}", "fields": [{"key": "nick", "label": "Ваш игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "offender", "label": "Игровой ник нарушителя", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "rule", "label": "Нарушение", "type": "text", "required": true, "placeholder": "Например: DM в зелёной зоне", "max": 100}, {"key": "essence", "label": "Суть жалобы", "type": "textarea", "required": true}, {"key": "date", "label": "Дата нарушения", "type": "date", "required": true}, {"key": "time", "label": "Время нарушения (МСК)", "type": "text", "placeholder": "21:10", "max": 20}, {"key": "proof", "label": "Доказательства", "type": "url", "required": true, "hint": "Ссылка на видео (YouTube) или скриншот."}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
  (53, 51, 'forum', 'Жалобы на администрацию', 'Неверное наказание или поведение администратора', 'shield', 2, 0, 10, 10, 0, 0, 4, 1, 1, 'Жалоба на администратора Nick_Name | Причина', '[b]1. Ваш игровой ник:[/b] \n[b]2. Игровой ник администратора:[/b] \n[b]3. Выданное наказание и его причина:[/b] \n[b]4. Суть жалобы:[/b] \n[b]5. Дата и время (МСК):[/b] \n[b]6. Скриншот выдачи наказания:[/b] \n[b]7. Скриншот /time при входе в игру:[/b] ', '{"title": "Жалоба на администратора {admin} | Причина: {reason}", "fields": [{"key": "kind", "label": "Тип жалобы", "type": "radio", "required": true, "options": ["Жалоба на администрацию", "Жалоба на старшую администрацию"]}, {"key": "nick", "label": "Ваш игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "admin", "label": "Игровой ник администратора", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "reason", "label": "Причина наказания", "type": "text", "required": true, "max": 100, "hint": "Причину наказания можно посмотреть в игре в истории наказаний."}, {"key": "essence", "label": "Суть жалобы", "type": "textarea", "required": true}, {"key": "proof", "label": "Скриншот истории наказания", "type": "url", "hint": "Загрузите скриншот на imgur.com или yapx.ru и вставьте ссылку."}, {"key": "proof2", "label": "Скриншот при входе в игру (при бане)", "type": "url", "hint": "Загрузите скриншот на imgur.com или yapx.ru и вставьте ссылку."}, {"key": "date", "label": "Дата выдачи наказания", "type": "date", "required": true}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
  (54, 51, 'forum', 'Жалобы на лидеров и заместителей', 'Нарушения со стороны руководства Правительства и Департамента полиции', 'crown', 3, 0, 10, 10, 0, 0, 5, 1, 1, 'Жалоба на лидера Nick_Name | Организация', '[b]1. Ваш игровой ник:[/b] \n[b]2. Игровой ник лидера или заместителя:[/b] \n[b]3. Организация:[/b] \n[b]4. Суть жалобы:[/b] \n[b]5. Дата и время (МСК):[/b] \n[b]6. Доказательства (скриншоты, видео):[/b] ', '{"title": "Жалоба на лидера {leader} | {org}", "fields": [{"key": "nick", "label": "Ваш игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "leader", "label": "Ник лидера или заместителя", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "org", "label": "Организация", "type": "text", "required": true, "max": 60}, {"key": "essence", "label": "Суть жалобы", "type": "textarea", "required": true}, {"key": "date", "label": "Дата нарушения", "type": "date", "required": true}, {"key": "proof", "label": "Доказательства", "type": "url", "required": true, "hint": "Ссылка на видео (YouTube) или скриншот."}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
  (55, 51, 'forum', 'Обжалование наказаний', 'Просьбы о снятии или смягчении наказания', 'ban', 4, 0, 10, 10, 0, 0, 6, 1, 1, 'Обжалование наказания Nick_Name', '[b]1. Ваш игровой ник:[/b] \n[b]2. Ник администратора, выдавшего наказание:[/b] \n[b]3. Наказание (бан, мут, варн, деморган) и срок:[/b] \n[b]4. Причина наказания:[/b] \n[b]5. Почему наказание стоит снять или смягчить:[/b] \n[b]6. Скриншот наказания:[/b] ', '{"title": "Обжалование наказания {nick} | {punishment}", "fields": [{"key": "nick", "label": "Ваш игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "admin", "label": "Ник администратора, выдавшего наказание", "type": "text", "required": true, "max": 32}, {"key": "punishment", "label": "Наказание", "type": "select", "required": true, "options": ["Бан", "Варн", "Мут", "Деморган", "Тюрьма", "Другое"]}, {"key": "term", "label": "Срок наказания", "type": "text", "required": true, "placeholder": "Например: 3 дня", "max": 40}, {"key": "reason", "label": "Причина наказания", "type": "text", "required": true, "max": 100}, {"key": "why", "label": "Почему наказание стоит снять или смягчить", "type": "textarea", "required": true}, {"key": "proof", "label": "Скриншот наказания", "type": "url", "hint": "Загрузите скриншот на imgur.com или yapx.ru и вставьте ссылку."}, {"key": "date", "label": "Дата выдачи наказания", "type": "date", "required": true}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
  (56, 50, 'forum', 'Государственные организации', 'Правительство и Департамент полиции', 'building', 2, 0, 80, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (57, 56, 'forum', 'Правительство', 'Мэрия Лос-Сантоса: новости, собеседования, заявления', 'building', 1, 0, 10, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (58, 56, 'forum', 'Департамент полиции', 'Новости департамента, набор в академию, отчёты', 'shield', 2, 0, 10, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL),
  (67, 50, 'forum', 'Заявления на пост лидера', 'Хотите возглавить организацию - подайте заявление', 'crown', 4, 0, 10, 10, 0, 0, 7, 1, 1, 'Заявление на пост лидера | Организация', '[b]1. Игровой ник:[/b] \n[b]2. Реальный возраст:[/b] \n[b]3. Игровой уровень:[/b] \n[b]4. На какую организацию претендуете:[/b] \n[b]5. Опыт лидерства (где и когда):[/b] \n[b]6. Сколько часов в день готовы играть:[/b] \n[b]7. Наказания за последние 30 дней:[/b] \n[b]8. Почему именно вы:[/b] ', '{"title": "Заявление на пост лидера | {org} | {nick}", "fields": [{"key": "nick", "label": "Игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "org", "label": "Организация", "type": "text", "required": true, "max": 60}, {"key": "age", "label": "Реальный возраст", "type": "number", "required": true, "max": 3}, {"key": "level", "label": "Игровой уровень", "type": "number", "required": true, "max": 4}, {"key": "exp", "label": "Опыт лидерства (где и когда)", "type": "textarea", "required": true}, {"key": "hours", "label": "Сколько часов в день готовы играть", "type": "text", "required": true, "max": 40}, {"key": "punish", "label": "Наказания за последние 30 дней", "type": "text", "required": true, "placeholder": "Нет / перечислите", "max": 200}, {"key": "why", "label": "Почему именно вы", "type": "textarea", "required": true}, {"key": "discord", "label": "Discord для связи", "type": "text", "max": 64}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
  (68, 50, 'forum', 'Набор в администрацию', 'Заявления в команду администрации сервера', 'shield', 5, 0, 10, 10, 0, 0, 8, 1, 1, 'Заявление в администрацию | Nick_Name', '[b]1. Игровой ник:[/b] \n[b]2. Реальный возраст:[/b] \n[b]3. Игровой уровень:[/b] \n[b]4. Опыт работы в администрации (где и когда):[/b] \n[b]5. Знание правил сервера (оцените от 1 до 10):[/b] \n[b]6. Сколько часов в день готовы уделять серверу:[/b] \n[b]7. Наказания за последние 30 дней:[/b] \n[b]8. Почему именно вы:[/b] ', '{"title": "Заявление в администрацию | {nick}", "fields": [{"key": "nick", "label": "Игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "age", "label": "Реальный возраст", "type": "number", "required": true, "max": 3}, {"key": "level", "label": "Игровой уровень", "type": "number", "required": true, "max": 4}, {"key": "exp", "label": "Опыт в администрации (где и когда)", "type": "textarea", "required": true}, {"key": "rules", "label": "Знание правил сервера", "type": "select", "required": true, "options": ["Отлично", "Хорошо", "Средне"]}, {"key": "hours", "label": "Сколько часов в день готовы уделять серверу", "type": "text", "required": true, "max": 40}, {"key": "punish", "label": "Наказания за последние 30 дней", "type": "text", "required": true, "placeholder": "Нет / перечислите", "max": 200}, {"key": "why", "label": "Почему именно вы", "type": "textarea", "required": true}, {"key": "discord", "label": "Discord для связи", "type": "text", "required": true, "max": 64}, {"key": "agree", "label": "Готов нести ответственность в случае обмана", "type": "checkbox", "text": "Да", "required": true, "hint": "Вы подтверждаете, что всё написанное - правда, и готовы понести наказание, если обман будет доказан."}]}'),
